1	/****************************************************************************
2	 * app/home_scense/ui_voice.c
3	 * AI conversation home page below the shared status bar.
4	 *
5	 * 多轮对话历史:每轮追加"你/豆包"两条气泡,历史保留、自动滚到底。
6	 * 按钮为点击切换(点一下开始录音 / 再点一下结束并等待回复),配合常驻会话:
7	 * 应用启动即连接豆包,每次录音只是同一连接上的新一轮,无需每轮重连。
8	 ****************************************************************************/
9	
10	#include "ui_voice.h"
11	#include "main.h"
12	#include "ui_emoji_idle.h"
13	#include "wifi_status.h"
14	#include "doubao/doubao_voice.h"
15	
16	#include <string.h>
17	
18	static lv_obj_t *g_messages;
19	static lv_obj_t *g_action;
20	static lv_obj_t *g_action_label;
21	static lv_obj_t *g_state_label;
22	
23	/* 当前轮的气泡(实时更新);turn_seq 变化即沉淀为历史、清引用 */
24	static lv_obj_t *g_cur_user_bubble;
25	static lv_obj_t *g_cur_ai_bubble;
26	static unsigned  g_cur_turn;
27	static char g_last_user[DOUBAO_TEXT_MAX];
28	static char g_last_reply[DOUBAO_REPLY_MAX];
29	
30	typedef enum {
31	    VOICE_ANIMATION_NONE,
32	    VOICE_ANIMATION_LISTEN,
33	    VOICE_ANIMATION_SPEAK,
34	} voice_animation_t;
35	
36	static voice_animation_t g_voice_animation;
37	
38	static void update_voice_animation(doubao_voice_state_t state)
39	{
40	    voice_animation_t next = VOICE_ANIMATION_NONE;
41	    const char *name = NULL;
42	
43	    if (state == DOUBAO_VOICE_LISTENING ||
44	        state == DOUBAO_VOICE_RECORDING) {
45	        next = VOICE_ANIMATION_LISTEN;
46	        name = "listen";
47	    } else if (state == DOUBAO_VOICE_PLAYING) {
48	        next = VOICE_ANIMATION_SPEAK;
49	        name = "speak";
50	    }
51	
52	    if (next == g_voice_animation) return;
53	
54	    /* Route through the priority arbiter as the VOICE source: listen/speak
55	     * outrank the Claude MQTT status, so an active conversation is never
56	     * masked by the agent状态动画;NULL 时撤回本源请求,交回给 Claude/待机。 */
57	    emoji_idle_request(EMOJI_SRC_VOICE, name);
58	    g_voice_animation = next;
59	}
60	
61	/* 新增/更新气泡:传入已存在的 bubble 则更新其文字,否则新建并返回。 */
62	static lv_obj_t *set_bubble(lv_obj_t *existing, const char *prefix,
63	                            const char *text, bool user)
64	{
65	    lv_obj_t *bubble;
66	    lv_obj_t *label;
67	
68	    if (!text || !text[0]) return existing;
69	
70	    if (existing) {
71	        label = lv_obj_get_child(existing, 0);
72	        if (label) lv_label_set_text_fmt(label, "%s%s", prefix, text);
73	        lv_obj_scroll_to_view(existing, LV_ANIM_ON);
74	        return existing;
75	    }
76	
77	    bubble = lv_obj_create(g_messages);
78	    lv_obj_set_width(bubble, 220);
79	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
80	    lv_obj_set_style_bg_color(bubble,
81	                              user ? lv_color_hex(0x1F618D) :
82	                                     lv_color_hex(0x273746), 0);
83	    lv_obj_set_style_bg_opa(bubble, LV_OPA_COVER, 0);
84	    lv_obj_set_style_border_width(bubble, 0, 0);
85	    lv_obj_set_style_radius(bubble, 8, 0);
86	    lv_obj_set_style_pad_all(bubble, 7, 0);
87	    lv_obj_set_style_margin_top(bubble, 4, 0);
88	    lv_obj_set_style_margin_bottom(bubble, 4, 0);
89	    lv_obj_set_style_margin_left(bubble, user ? 78 : 4, 0);
90	    lv_obj_set_style_margin_right(bubble, user ? 4 : 78, 0);
91	    lv_obj_clear_flag(bubble, LV_OBJ_FLAG_SCROLLABLE);
92	
93	    label = lv_label_create(bubble);
94	    lv_obj_set_width(label, 205);
95	    lv_label_set_text_fmt(label, "%s%s", prefix, text);
96	    lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
97	    lv_obj_set_style_text_font(label, g_misans_normal_12, 0);
98	    lv_obj_set_style_text_color(label, lv_color_hex(0xF7F9F9), 0);
99	    lv_obj_scroll_to_view(bubble, LV_ANIM_ON);
100	    return bubble;
101	}
102	
103	static const char *status_text(doubao_voice_state_t state)
104	{
105	    switch (state) {
106	    case DOUBAO_VOICE_UNCONFIGURED: return "请先配置豆包凭证";
107	    case DOUBAO_VOICE_IDLE: return "点击说话";
108	    case DOUBAO_VOICE_CONNECTING: return "正在连接豆包…";
109	    case DOUBAO_VOICE_LISTENING: return "聆听中…请说话";
110	    case DOUBAO_VOICE_RECORDING: return "正在识别…";
111	    case DOUBAO_VOICE_WAITING_RESPONSE: return "思考中…";
112	    case DOUBAO_VOICE_PLAYING: return "豆包正在回答…";
113	    case DOUBAO_VOICE_ERROR: return "语音服务发生错误";
114	    default: return "";
115	    }
116	}
117	
118	/* 全双工:点击切换会话。待命(未 talking)点击 → 开始连续对话;对话中(任一
119	 * 聆听/识别/思考/回答态)点击 → 停止会话。用 doubao_voice_is_talking() 判定,
120	 * 不再维护本地 toggle,避免与真实状态错位。 */
121	static void action_click_cb(lv_event_t *event)
122	{
123	    static uint32_t last_click;
124	    uint32_t now;
125	
126	    (void)event;
127	    home_record_activity();
128	
129	    /* 点击去抖:触摸屏偶尔把一次点击弹成两次 CLICKED。350ms 内重复忽略。 */
130	    now = lv_tick_get();
131	    if (now - last_click < 350) {
132	        return;
133	    }
134	    last_click = now;
135	
136	    if (!wifi_status_is_connected()) {
137	        return;
138	    }
139	    if (doubao_voice_is_talking()) {
140	        (void)doubao_voice_stop();
141	    } else {
142	        (void)doubao_voice_start();
143	    }
144	}
145	
146	void ui_voice_create(lv_obj_t *parent)
147	{
148	    g_messages = lv_obj_create(parent);
149	    lv_obj_set_size(g_messages, SCREEN_WIDTH - 16, 150);
150	    lv_obj_align(g_messages, LV_ALIGN_TOP_MID, 0, 34);
151	    lv_obj_set_style_bg_opa(g_messages, LV_OPA_TRANSP, 0);
152	    lv_obj_set_style_border_width(g_messages, 0, 0);
153	    lv_obj_set_style_pad_all(g_messages, 2, 0);
154	    lv_obj_set_flex_flow(g_messages, LV_FLEX_FLOW_COLUMN);
155	    lv_obj_set_scroll_dir(g_messages, LV_DIR_VER);
156	
157	    g_state_label = lv_label_create(parent);
158	    lv_obj_set_width(g_state_label, SCREEN_WIDTH - 24);
159	    lv_obj_align(g_state_label, LV_ALIGN_BOTTOM_MID, 0, -48);
160	    lv_obj_set_style_text_font(g_state_label, g_misans_normal_11, 0);
161	    lv_obj_set_style_text_align(g_state_label, LV_TEXT_ALIGN_CENTER, 0);
162	    lv_obj_set_style_text_color(g_state_label, lv_color_hex(0xAED6F1), 0);
163	
164	    g_action = lv_button_create(parent);
165	    lv_obj_set_size(g_action, SCREEN_WIDTH - 16, 36);
166	    lv_obj_align(g_action, LV_ALIGN_BOTTOM_MID, 0, -7);
167	    lv_obj_set_style_bg_color(g_action, lv_color_hex(0x1F618D), 0);
168	    lv_obj_set_style_border_width(g_action, 0, 0);
169	    lv_obj_set_style_radius(g_action, 8, 0);
170	    lv_obj_add_event_cb(g_action, action_click_cb, LV_EVENT_CLICKED, NULL);
171	    g_action_label = lv_label_create(g_action);
172	    lv_obj_set_style_text_font(g_action_label, g_misans_normal_16, 0);
173	    lv_obj_set_style_text_color(g_action_label, lv_color_hex(0xF7F9F9), 0);
174	    lv_obj_center(g_action_label);
175	}
176	
177	void ui_voice_refresh(lv_timer_t *timer)
178	{
179	    /* snapshot 含 assistant_text[DOUBAO_REPLY_MAX=8192],放栈上约 9KB,叠加
180	     * LVGL 主线程调用链易压爆 100KB 栈。改 static:refresh 由 LVGL 单线程
181	     * 周期调用,无并发,与 g_last_user/g_last_reply 一致。 */
182	    static doubao_voice_snapshot_t snapshot;
183	
184	    (void)timer;
185	    if (!g_action) return;
186	    doubao_voice_get_snapshot(&snapshot);
187	    update_voice_animation(snapshot.state);
188	
189	    /* 新一轮开始:上一轮气泡已沉淀为历史,清空当前轮引用 */
190	    if (snapshot.turn_seq != g_cur_turn) {
191	        g_cur_turn = snapshot.turn_seq;
192	        g_cur_user_bubble = NULL;
193	        g_cur_ai_bubble = NULL;
194	        g_last_user[0] = '\0';
195	        g_last_reply[0] = '\0';
196	    }
197	
198	    if (snapshot.user_text[0] && strcmp(snapshot.user_text, g_last_user) != 0) {
199	        strncpy(g_last_user, snapshot.user_text, sizeof(g_last_user) - 1);
200	        g_cur_user_bubble = set_bubble(g_cur_user_bubble, "你：",
201	                                       snapshot.user_text, true);
202	    }
203	    if (snapshot.assistant_text[0] &&
204	        strcmp(snapshot.assistant_text, g_last_reply) != 0) {
205	        strncpy(g_last_reply, snapshot.assistant_text, sizeof(g_last_reply) - 1);
206	        g_cur_ai_bubble = set_bubble(g_cur_ai_bubble, "豆包：",
207	                                     snapshot.assistant_text, false);
208	    }
209	
210	    lv_label_set_text(g_state_label,
211	                      snapshot.state == DOUBAO_VOICE_ERROR &&
212	                      snapshot.error_text[0] ? snapshot.error_text :
213	                      status_text(snapshot.state));
214	
215	    /* 全双工按钮:
216	     *  - 未配置 / Wi-Fi 未连 / 连接中 → 禁用,提示原因
217	     *  - 对话中(talking:聆听/识别/思考/回答任一态)→ "停止对话"(红),可点
218	     *  - 待命(IDLE)→ "开始对话"(蓝),可点
219	     *  - ERROR → "点击重试"(橙),可点(触发重新开始) */
220	    if (snapshot.state == DOUBAO_VOICE_UNCONFIGURED) {
221	        lv_label_set_text(g_action_label, "请先配置豆包凭证");
222	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
223	        lv_obj_add_state(g_action, LV_STATE_DISABLED);
224	    } else if (!wifi_status_is_connected()) {
225	        lv_label_set_text(g_action_label, "Wi-Fi 未连接");
226	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
227	        lv_obj_add_state(g_action, LV_STATE_DISABLED);
228	    } else if (snapshot.state == DOUBAO_VOICE_CONNECTING) {
229	        lv_label_set_text(g_action_label, "连接中…");
230	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
231	        lv_obj_add_state(g_action, LV_STATE_DISABLED);
232	    } else if (doubao_voice_is_talking()) {
233	        lv_label_set_text(g_action_label, "停止对话");
234	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0xC0392B), 0);
235	        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
236	    } else if (snapshot.state == DOUBAO_VOICE_ERROR) {
237	        lv_label_set_text(g_action_label, "点击重试");
238	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0xD68910), 0);
239	        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
240	    } else {
241	        lv_label_set_text(g_action_label, "开始对话");
242	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x1F618D), 0);
243	        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
244	    }
245	}
